Definition ninv {HCEIL : HeapCeil} (lo shi : Z) (M : mem) : Prop := mem_inv asegs M /\ ACONST M /\ stack0 M lo shi /\ relro_clear M.

Lemma ninv_stores {HCEIL : HeapCeil} : forall lo shi M M' (a b : Z), ninv lo shi M -> stores_in (zwin a b) M M' ->
